               - unfold bapart, aapart. rewrite !map_app. cbn [map bn_addr bn_of b_addr]. rewrite <- app_assoc. cbn [app]. rewrite map_app in NDad, APad. split.
                 + apply NoDup_insert_mid; [exact NDad|]. rewrite <- map_app. intros IN. apply ADR in IN as (b0 & Hb0 & E). pose proof (BBT b0 Hb0) as Y. clear - Y E. lia.
                 + intros x y Hx Hy NE. rewrite <- map_app in APad.
                   apply in_app_iff in Hx. apply in_app_iff in Hy. cbn [In] in Hx, Hy.
                   assert (CX : In x (map bn_addr (tbs ++ gbs)) \/ x = b) by (rewrite map_app; destruct Hx as [Hx|[Hx|Hx]]; [left; apply in_app_iff; left; exact Hx| right; symmetry; exact Hx| left; apply in_app_iff; right; exact Hx]).
                   assert (CY : In y (map bn_addr (tbs ++ gbs)) \/ y = b) by (rewrite map_app; destruct Hy as [Hy|[Hy|Hy]]; [left; apply in_app_iff; left; exact Hy| right; symmetry; exact Hy| left; apply in_app_iff; right; exact Hy]).
                   destruct CX as [CX| ->]; destruct CY as [CY| ->].
                   * exact (APad x y CX CY NE).
                   * apply ADR in CX as (b0 & Hb0 & <-). pose proof (BBT b0 Hb0) as Y. clear - Y. lia.
                   * apply ADR in CY as (b0 & Hb0 & <-). pose proof (BBT b0 Hb0) as Y. clear - Y. lia.
                   * exfalso. exact (NE eq_refl). }
      split. { eapply keep_rw; [exact MTX| eapply (iagree_kept quar_img_ranges); [apply IAG; vm_compute; reflexivity| cbn [cells_size csize length Nat.add Nat.mul]; vm_compute; reflexivity]| exact WM]. }
      split; [rewrite EQ4; clear - EBT; lia| exact EBG]. }
    idtac "MARK-6-GQ2-done".
    (* [comment removed for export] *)
    assert (NBLK : forall a, p - 16 <= a < p + 8 * kk -> ~ in_blk (blocks h2) a).
    { (intros a Ha dd_H; ddestruct dd_H as (bk & Hbk & Ra)). destruct bk as [B N0']. cbn [fst snd] in Ra.
      ddestruct (blocks_In h2 B N0' Hbk) as (kb & Hkb & STb & EBu & ENb).
      change (h_chunks h2) with (quar_ab (ck_ab k) (h_chunks h)) in Hkb. apply quar_ab_In in Hkb. ddestruct Hkb as (k0 & Hk0 & Ekb).
      revert STb EBu ENb. rewrite Ekb. destruct (Z.eqb_spec (ck_ab k0) (ck_ab k)) as [EQ|NE]; intros STb EBu ENb; [cbv in STb; discriminate STb|]. cbv iota in STb, EBu, ENb.
      pose proof (ext_disj' h k0 k WL WR WK GEOh Hk0 Hk NE) as XD.
      ddestruct (chunk_ext' h k0 WL WR WK Hk0) as (N00 & F1 & F2 & F3 & F4 & _).
      clear - Ha Ra XD F1 F2 F3 F4 EBu ENb E1 E2 URE. subst B N0' p. lia. }
    assert (BBLK : forall a, b <= a < b + 8192 -> ~ in_blk (blocks h2) a).
    { (intros a Ha dd_H; ddestruct dd_H as (bk & Hbk & Ra)). destruct bk as [B N0']. cbn [fst snd] in Ra.
      ddestruct (blocks_In h2 B N0' Hbk) as (kb & Hkb & STb & EBu & ENb).
      change (h_chunks h2) with (quar_ab (ck_ab k) (h_chunks h)) in Hkb. apply quar_ab_In in Hkb. ddestruct Hkb as (k0 & Hk0 & Ekb).
      revert STb EBu ENb. rewrite Ekb. destruct (Z.eqb_spec (ck_ab k0) (ck_ab k)) as [EQ|NE]; intros STb EBu ENb; [cbv in STb; discriminate STb|]. cbv iota in STb, EBu, ENb.
      ddestruct (chunk_ext' h k0 WL WR WK Hk0) as (N00 & F1 & F2 & F3 & F4 & _).
      pose proof (cache_vs_chunk h kBatchClass q kq k0 WL WR WK GEOh ltac:(unfold kBatchClass; clear; lia) INQ Hkq EKQ' Hk0) as BV0. fold L in BV0. rewrite BCH in BV0.
      change (class_size kBatchClass) with 8192 in BV0. clear - Ha Ra BV0 F1 F2 F3 EBu ENb. subst B N0'. lia. }
    assert (BATNB : forall b0 a, In b0 (q_batches (h_tq h) ++ q_batches (h_gq h)) -> b_addr b0 <= a < b_addr b0 + 8192 -> ~ in_blk (blocks h2) a).
    { (intros b0 a Hb0 Ha dd_H; ddestruct dd_H as (bk & Hbk & Ra)). destruct bk as [B N0']. cbn [fst snd] in Ra.
      ddestruct (blocks_In h2 B N0' Hbk) as (kb & Hkb & STb & EBu & ENb).
      change (h_chunks h2) with (quar_ab (ck_ab k) (h_chunks h)) in Hkb. apply quar_ab_In in Hkb. ddestruct Hkb as (k0 & Hk0 & Ekb).
      revert STb EBu ENb. rewrite Ekb. destruct (Z.eqb_spec (ck_ab k0) (ck_ab k)) as [EQ|NE]; intros STb EBu ENb; [cbv in STb; discriminate STb|]. cbv iota in STb, EBu, ENb.
      ddestruct (chunk_ext' h k0 WL WR WK Hk0) as (N00 & F1 & F2 & F3 & F4 & _ & _ & FC).
      destruct FC as [(P' & _)|(P' & i' & Ni0 & ELST' & EH')].
      - pose proof (batch_vs_chunk h k0 b0 (WFR_of_awf' h AWF) Hk0 P' Hb0) as BV. unfold ext_lo in F1. unfold ext_hi, ck_end in F3. rewrite P' in F1, F3.
        clear - Ha Ra BV F1 F2 F3 EBu ENb. subst B N0'. lia.
      - pose proof (z_sec_hull h GEOh i' _ Ni0) as Y. unfold zapart in Y. cbn [fst snd s_map_beg s_map_size] in Y. ddestruct (BHF b0 Hb0) as (H1 & H2 & _).
        clear - Ha Ra Y ELST' EH' F1 F2 F3 EBu ENb H1 H2. subst B N0' L. lia. }
    assert (QSK : ck_prim k = false -> In (ck_map_beg k, ck_map_size k) (qs_of h2)).
    { intros PK. apply (qs_of_In h2 (quar k)); [| exact PK| reflexivity].
      change (h_chunks h2) with (quar_ab (ck_ab k) (h_chunks h)). apply quar_ab_In. exists k. rewrite Z.eqb_refl. split; [exact Hk| reflexivity]. }
    assert (ZP : forall a, p - 16 <= a < p + 8 * kk ->
              (in_hull L a /\ ~ in_blk (blocks h2) a) \/ (exists q, In q (qs_of h2) /\ (fst q <= a < fst q + snd q \/ shad (fst q) <= a < shad (fst q) + snd q / 8))).
    { intros a Ha. destruct (ck_prim k) eqn:PK.
      - left. dpose (EXTH eq_refl) as (X1 & X2 & _). split; [unfold in_hull; clear - Ha X1 X2 E1 E2 URE; subst p; lia| exact (NBLK a Ha)].
      - right. dpose (EXTS eq_refl) as (i & Ni & XL & XH & _). exists (ck_map_beg k, ck_map_size k). split; [exact (QSK eq_refl)|].
        left. cbn [fst snd]. clear - Ha XL XH E1 E2 URE; subst p; lia. }
    assert (ZSH : forall a, Sh <= a < Sh + kk ->
              (shad (l_b6 L) <= a < shad (l_b6 L + 0x2000011000) /\ ~ (exists c, in_blk (blocks h2) c /\ a = shad c))
              \/ (exists q, In q (qs_of h2) /\ (fst q <= a < fst q + snd q \/ shad (fst q) <= a < shad (fst q) + snd q / 8))).
    { intros a Ha. pose proof (Z.div_mod p 8 ltac:(clear; lia)) as Dp. rewrite U8, Z.add_0_r in Dp. destruct (ck_prim k) eqn:PK.
      - left. dpose (EXTH eq_refl) as (X1 & X2 & _). split.
        + unfold shad. subst Sh. clear - Ha X1 X2 E1 E2 URE KKB Dp; subst p. lia.
        + (intros dd_H; ddestruct dd_H as (c & BLc & Ec)). unfold shad in Ec. apply (NBLK c); [| exact BLc]. subst Sh. clear - Ha Ec Dp KKB. lia.
      - right. dpose (EXTS eq_refl) as (i & Ni & XL & XH & MB & _). exists (ck_map_beg k, ck_map_size k). split; [exact (QSK eq_refl)|].
        right. cbn [fst snd]. unfold shad. subst Sh. pose proof (Z.div_mod (ck_map_beg k) 4096 ltac:(clear; lia)) as Dm. rewrite MB, Z.add_0_r in Dm.
        clear - Ha XL XH E1 E2 URE KKB Dp Dm; subst p. lia. }
    assert (FK1 : fkeepR L (blocks h2) (qs_of h2) (rp_of h2) nb' bl' lo SP m m1).
    { apply (fkeepR_of_munch L _ _ _ nb' bl' lo SP (fsegQ_W p lo SP T) m m1 MU1). unfold fsegQ_W, ia_W. cbn [app].
      repeat apply Forall_cons;
        [ intros a Ha; cbn [fst snd] in Ha; right; left; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; left; exact Ha
        | intros a Ha; cbn [fst snd] in Ha; do 5 right; left; unfold free_img_ranges; cbn [in_rangesZ]; unfold A_IA, A_IA_INIT, A_INSTANCE in Ha |- *; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; do 5 right; left; unfold free_img_ranges; cbn [in_rangesZ]; unfold A_IA, A_IA_INIT, A_INSTANCE in Ha |- *; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; do 5 right; left; unfold free_img_ranges; cbn [in_rangesZ]; unfold A_IA, A_IA_INIT, A_INSTANCE in Ha |- *; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; do 5 right; left; unfold free_img_ranges; cbn [in_rangesZ]; unfold A_IA, A_IA_INIT, A_INSTANCE in Ha |- *; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; do 5 right; left; unfold free_img_ranges; cbn [in_rangesZ]; unfold A_IA, A_IA_INIT, A_INSTANCE in Ha |- *; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; do 5 right; left; unfold free_img_ranges; cbn [in_rangesZ]; unfold A_IA, A_IA_INIT, A_INSTANCE in Ha |- *; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; destruct (ZP a ltac:(clear - Ha KKB; lia)) as [X|X]; [do 2 right; left; exact X| do 4 right; left; exact X]
        | intros a Ha; cbn [fst snd] in Ha; destruct (ZP a ltac:(clear - Ha KKB; lia)) as [X|X]; [do 2 right; left; exact X| do 4 right; left; exact X]
        | intros a Ha; cbn [fst snd] in Ha; right; left; clear - Ha; lia
        | apply Forall_nil ]. }
    assert (FK2 : fkeepR L (blocks h2) (qs_of h2) (rp_of h2) nb' bl' lo SP m1 m3).
    { intros x. cbv zeta. intros Z1 Z2 Z3 Z4 Z5 Z6 Z7 Z8 Z9 Z10. apply DK3.
