    assert (FK3 : fkeepR L (blocks h2) (qs_of h2) (rp_of h2) nb' bl' lo SP m3 m4).
    { apply (fkeepR_of_munch L _ _ _ nb' bl' lo SP (fsegPH_W p lo SP T lst b nx (Z.of_nat (length tbs))) m3 m4 MU4). unfold fsegPH_W. rewrite <- Ekk. fold Sh. fold lw.
      repeat apply Forall_cons;
        [ intros a Ha; cbn [fst snd] in Ha; left; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; destruct (ZP a ltac:(clear - Ha KKB; lia)) as [X|X]; [do 2 right; left; exact X| do 4 right; left; exact X]
        | intros a Ha; cbn [fst snd] in Ha; destruct (ZSH a Ha) as [X|X]; [do 3 right; left; exact X| do 4 right; left; exact X]
        | intros a Ha; cbn [fst snd] in Ha; right; left; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; right; left; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; right; left; clear - Ha; lia
        | intros a Ha; cbn [fst snd] in Ha; do 2 right; left; split; [unfold in_hull; clear - Ha BHU1 BHU2; subst L; lia| exact (BBLK a ltac:(clear - Ha; lia))]
        | intros a Ha; cbn [fst snd] in Ha; destruct LSTF as [(_ & L0 & W0)|(tq0 & lb & ETQ & ETB & ELST & ELB & W8 & FULL)]; [exfalso; rewrite W0 in Ha; clear - Ha; lia|];
          rewrite ELST, W8 in Ha; assert (INLB : In lb (q_batches (h_tq h) ++ q_batches (h_gq h))) by (rewrite ETQ; apply in_app_iff; left; apply in_app_iff; right; left; reflexivity);
          ddestruct (BHF lb INLB) as (LH1 & LH2 & _);
