        | apply Forall_nil ]. }
    assert (FK : fkeepR L (blocks h2) (qs_of h2) (rp_of h2) nb' bl' lo SP m m4).
    { exact (fkeepR_trans L _ _ _ nb' bl' nb' bl' lo SP m m1 m4 FK1 (fkeepR_trans L _ _ _ nb' bl' nb' bl' lo SP m1 m3 m4 FK2 FK3 (incl_refl _) (incl_refl _)) (incl_refl _) (incl_refl _)). }
