    assert (CSJ3 : rw_cells asegs m3 STK ([C8 (Z_to_bv 64 (STK + 16)); C8 (Z_to_bv 64 size)] ++ (map C8 ws ++ ([CB 1800 fr1] ++ ([C8 (Z_to_bv 64 SP)] ++ [CB 8 fr2]))))).
    { apply (proj2 (rw_cells_app asegs m3 STK _ _)). split; [exact STKC3|]. match goal with |- rw_cells _ _ ?a _ => replace a with (STK + 16) by (cbn; clear; lia) end.
      apply (proj2 (rw_cells_app asegs m3 (STK + 16) _ _)). split; [exact (u64arr_cells m3 _ _ HTR3)|]. rewrite AW_RecChunk.cells_size_C8s, HL30.
      match goal with |- rw_cells _ _ ?a _ => replace a with (STK + 256) by (clear; lia) end.
      apply (proj2 (rw_cells_app asegs m3 (STK + 256) _ _)). split; [exact F1800'|]. match goal with |- rw_cells _ _ ?a _ => replace a with (STK + 2056) by (cbn [cells_size csize Nat.add]; change (Z.of_nat 1800) with 1800; clear; lia) end.
      apply (proj2 (rw_cells_app asegs m3 (STK + 2056) _ _)). split; [exact TFB'|]. match goal with |- rw_cells _ _ ?a _ => replace a with (STK + 2064) by (cbn; clear; lia) end. exact F8'. }
    assert (SZJ : Z.of_nat (cells_size ([C8 (Z_to_bv 64 (STK + 16)); C8 (Z_to_bv 64 size)] ++ (map C8 ws ++ ([CB 1800 fr1] ++ ([C8 (Z_to_bv 64 SP)] ++ [CB 8 fr2]))))) = 2072).
    { rewrite !cells_size_app, AW_RecChunk.cells_size_C8s, HL30. reflexivity. }
