        | clear - ZTS STKZ SPL; subst STK; lia| clear - ZTS STKZ SPL; subst STK; lia| clear - ZHS STKZ SPL BHU1 BHU2; subst STK L; lia
        | apply LAP; [clear - SPL LOIMG ACB; try subst STK; lia| destruct ZHS as [Z1|Z1]; [right; left; clear - Z1 STKZ SPL; try subst STK; lia| left; clear - Z1 STKZ SPL; try subst STK; lia]]]. }
    assert (CSJ4 : rw_cells asegs m4 STK ([C8 (Z_to_bv 64 (STK + 16)); C8 (Z_to_bv 64 size)] ++ (map C8 ws ++ ([CB 1800 fr1] ++ ([C8 (Z_to_bv 64 SP)] ++ [CB 8 fr2])))))
