    assert (FR7'' : rw_cells asegs m4 (SP + -56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
      by (eapply keep_rw; [exact FR7'| eapply kept_sub; [exact KSTK| subst STK; clear; lia| cbn; subst STK; clear; lia]| exact WM4]).
    assert (HFR2 : hfr h2 <= hfr h + (d + 3)).
    { apply (hfr_put h h2 d size D0); [clear - SZB SZD; lia| change (d_n (h_dep h2)) with N'; fold N; exact NB'| change (s_total (h_dep h2)) with tf'; fold tf; unfold sframes; clear - TFP; lia]. }
