    split; [reflexivity|]. split; [exact HK4'|]. split; [cbn [ms_mem] in HJ4; exact HJ4|]. split; [exact MI4|]. split; [exact HMQ2|]. split; [exact GQ2|]. split; [exact PF4|]. split; [exact ST4|].
    split; [exact CSJ4|]. split; [exact SZJ|]. split; [exact FR7''|]. split; [exact WF2|].
    split; [change (q_batches (h_tq h2)) with (q_batches (h_tq h) ++ [BA (chunk_at L kBatchClass kq) [ck_hdr k] (nx + 8192)]); destruct (q_batches (h_tq h)); discriminate|].
    split. { change (q_batches (h_tq h2)) with (q_batches (h_tq h) ++ [BA (chunk_at L kBatchClass kq) [ck_hdr k] (nx + 8192)]). rewrite map_app. fold tbs. cbn [map].
             rewrite bsum_app. cbn [bsum bn_size bn_of b_size]. unfold kQuarantineCache in TQ3. clear - EBT TQ3 NXB BS0. lia. }
